import os
import sys
import subprocess
import hashlib
import stat
import tempfile
import urllib.request
import urllib.error

def get_env_var(name, default=None):
    return os.environ.get(name, default)

def validate_url(url):
    if not url:
        return False
    if not url.startswith(('http://', 'https://')):
        return False
    return True

def download_file(url, filepath):
    try:
        with urllib.request.urlopen(url, timeout=30) as response:
            data = response.read()
        with open(filepath, 'wb') as f:
            f.write(data)
        return True
    except urllib.error.URLError:
        return False
    except Exception:
        return False

def set_secure_permissions(filepath):
    try:
        os.chmod(filepath, stat.S_IRUSR | stat.S_IWUSR | stat.S_IXUSR)
        return True
    except OSError:
        return False

def main():
    binary_url = get_env_var('BINARY_URL')
    config_url = get_env_var('CONFIG_URL')
    binary_path = '/tmp/downloaded_binary'
    config_path = '/tmp/downloaded_config'

    if not binary_url or not config_url:
        sys.exit(1)

    if not validate_url(binary_url) or not validate_url(config_url):
        sys.exit(1)

    try:
        if not download_file(binary_url, binary_path):
            sys.exit(1)
        if not download_file(config_url, config_path):
            sys.exit(1)

        if not set_secure_permissions(binary_path):
            sys.exit(1)

        if not os.path.isfile(binary_path) or not os.path.isfile(config_path):
            sys.exit(1)

        subprocess.run([binary_path, config_path], check=True)
    except subprocess.CalledProcessError:
        sys.exit(1)
    except Exception:
        sys.exit(1)
    finally:
        try:
            if os.path.exists(binary_path):
                os.remove(binary_path)
            if os.path.exists(config_path):
                os.remove(config_path)
        except OSError:
            pass

if __name__ == '__main__':
    main()
